240	    @Override
241	    @Transactional
242	    public void saveOwner(Owner owner) throws DataAccessException {
243	        if (owner.getTelephone() != null) {
244	            owner.setTelephone(normalizeTelephone(owner.getTelephone()));
245	        }
246	        if (owner.getEmail() != null) {
247	            owner.setEmail(normalizeEmail(owner.getEmail()));
248	        }
249	        if (owner.getAddress() != null) {
250	            owner.setAddress(normalizeAddress(owner.getAddress()));
251	        }
252	        if (owner.getRegistrationDate() == null) {
253	            owner.setRegistrationDate(LocalDate.now());
254	        }
255	        if (owner.getCustomerCode() == null) {
256	            owner.setCustomerCode(generateCustomerCode(owner));
257	        }
258	        if (owner.isNew()) {
259	            owner.setNamesakeCount(countNamesakes(owner));
260	        }
261	        assertTelephoneUnique(owner, owner.getTelephone());
262	        List<Owner> household = findHouseholdMembers(owner);
263	        assertHouseholdAllowed(owner, household);
264	        assignHousehold(owner, household);
265	        ownerRepository.save(owner);
266	    }
267	
268	    /**
269	     * Build a {@code customerCode} formatted {@code '<CITY3>-<LAST3>-<NNNN>'} where CITY3 is the
270	     * upper-cased first three letters of the owner's city, LAST3 the upper-cased first three
271	     * letters of {@code lastName}, and NNNN is a per-city 4-digit zero-padded sequence equal to
272	     * one more than the number of owners already in that city.
273	     */
274	    private String generateCustomerCode(Owner owner) {
275	        String cityPrefix = prefix3(owner.getCity());
276	        String lastNamePrefix = prefix3(owner.getLastName());
277	        long sequence = countOwnersInCity(owner.getCity()) + 1L;
278	        return String.format("%s-%s-%04d", cityPrefix, lastNamePrefix, sequence);
279	    }
280	
281	    private static String prefix3(String value) {
282	        return value.substring(0, Math.min(3, value.length())).toUpperCase(Locale.ROOT);
283	    }
284	
285	    private long countOwnersInCity(String city) {
286	        String normalized = normalizeHouseholdValue(city);
287	        return ownerRepository.findAll().stream()
288	                .filter(existing -> normalized.equals(normalizeHouseholdValue(existing.getCity())))
289	                .count();
290	    }
291	
292	    /**
293	     * Counts the existing owners that share both {@code firstName} and {@code lastName} with the
294	     * given new {@code owner}, compared case-insensitively (with incidental whitespace collapsed).
295	     * The owner being created is not itself persisted yet, so the result is the number of namesakes
296	     * that already existed before this create.
297	     */
298	    private int countNamesakes(Owner owner) {
299	        String firstName = normalizeHouseholdValue(owner.getFirstName());
300	        String lastName = normalizeHouseholdValue(owner.getLastName());
301	        int count = 0;
302	        for (Owner existing : ownerRepository.findAll()) {
303	            if (!existing.getId().equals(owner.getId())
304	                    && firstName.equals(normalizeHouseholdValue(existing.getFirstName()))
305	                    && lastName.equals(normalizeHouseholdValue(existing.getLastName()))) {
306	                count++;
307	            }
308	        }
309	        return count;
310	    }
311	
312	    private static String normalizeEmail(String email) {
313	        return email == null ? null : email.toLowerCase(Locale.ROOT);
314	    }
315	
316	    /** Common street-type abbreviations expanded during address normalization. */
317	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
318	        "ST", "STREET",
319	        "RD", "ROAD",
320	        "AVE", "AVENUE");
321	
322	    /**
323	     * Canonicalizes a postal address: trims and collapses runs of whitespace into a single space,
324	     * upper-cases, and expands common street-type abbreviations (ST->STREET, RD->ROAD, AVE->AVENUE)
325	     * as whole words. Returns {@code null} for a {@code null} input and an empty string when the
326	     * address is blank once whitespace is stripped, so the required-field check sees the normalized
327	     * form.
328	     */
329	    private static String normalizeAddress(String address) {
330	        if (address == null) {
331	            return null;
332	        }
333	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
334	        if (collapsed.isEmpty()) {
335	            return "";
336	        }
337	        String[] tokens = collapsed.split(" ");
338	        StringBuilder sb = new StringBuilder(collapsed.length());
339	        for (int i = 0; i < tokens.length; i++) {
340	            if (i > 0) {
341	                sb.append(' ');
342	            }
343	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
344	        }
345	        return sb.toString();
346	    }
347	
348	    private static String normalizeTelephone(String telephone) {
349	        return telephone == null ? null : E164Telephone.toE164(telephone);
350	    }
351	
352	    /**
353	     * Rejects saving {@code owner} when its {@code normalized} telephone is already used by any
354	     * other owner, so no two owners can share a telephone number.
355	     *
356	     * @throws DuplicateTelephoneException if another owner already has the same normalized telephone
357	     */
358	    private void assertTelephoneUnique(Owner owner, String normalized) {
359	        if (normalized == null || normalized.isEmpty()) {
360	            return;
361	        }
362	        for (Owner existing : ownerRepository.findAll()) {
363	            if (!existing.getId().equals(owner.getId())
364	                    && normalized.equals(normalizeTelephone(existing.getTelephone()))) {
365	                throw new DuplicateTelephoneException(normalized);
366	            }
367	        }
368	    }
369	
370	    /**
371	     * Returns the existing owners that share both {@code lastName} (compared case-insensitively with
372	     * collapsed whitespace) and the normalized {@code address} with a new {@code owner} — i.e. the
373	     * members of the household it would join. Returns an empty list for an update to an existing
374	     * owner or when either household value is blank, so household rules only apply to genuine new
375	     * members.
376	     */
377	    private List<Owner> findHouseholdMembers(Owner owner) {
378	        if (!owner.isNew()) {
379	            return List.of();
380	        }
381	        String lastName = normalizeHouseholdValue(owner.getLastName());
382	        String address = normalizeHouseholdAddress(owner.getAddress());
383	        if (lastName.isEmpty() || address.isEmpty()) {
384	            return List.of();
385	        }
386	        List<Owner> household = new ArrayList<>();
387	        for (Owner existing : ownerRepository.findAll()) {
388	            if (!existing.getId().equals(owner.getId())
389	                    && lastName.equals(normalizeHouseholdValue(existing.getLastName()))
390	                    && address.equals(normalizeHouseholdAddress(existing.getAddress()))) {
391	                household.add(existing);
392	            }
393	        }
394	        return household;
395	    }
396	
397	    /**
398	     * Pure guard: rejects creating {@code owner} when it would join a non-empty {@code household}
399	     * without acknowledging the shared household via {@link Owner#isSharesHousehold()}. Returns
400	     * without side effects otherwise.
401	     *
402	     * @throws DuplicateHouseholdException if another owner already lives at the same household and
403	     *                                     the request does not acknowledge the shared household
404	     */
405	    private void assertHouseholdAllowed(Owner owner, List<Owner> household) {
406	        if (!household.isEmpty() && !owner.isSharesHousehold()) {
407	            throw new DuplicateHouseholdException(owner.getLastName(), owner.getAddress());
408	        }
409	    }
410	
411	    /**
412	     * Assigns household membership when {@code owner} joins a non-empty {@code household}: the new
413	     * owner and every matching existing member that lacks one are given the same stable
414	     * {@code householdId}, and any updated existing members are persisted. No-op when the household
415	     * is empty.
416	     */
417	    private void assignHousehold(Owner owner, List<Owner> household) {
418	        if (household.isEmpty()) {
419	            return;
420	        }
421	        String householdId = resolveHouseholdId(owner, household);
422	        owner.setHouseholdId(householdId);
423	        for (Owner existing : household) {
424	            if (existing.getHouseholdId() == null || existing.getHouseholdId().isBlank()) {
425	                existing.setHouseholdId(householdId);
426	                ownerRepository.save(existing);
427	            }
428	        }
429	    }
430	
431	    /**
432	     * Returns the {@code householdId} shared by a household: the first non-blank identifier already
433	     * carried by an existing member, or otherwise a freshly derived stable identifier for the
434	     * joining {@code owner}'s normalized lastName and address.
435	     */
436	    private String resolveHouseholdId(Owner owner, List<Owner> household) {
437	        for (Owner existing : household) {
438	            if (existing.getHouseholdId() != null && !existing.getHouseholdId().isBlank()) {
439	                return existing.getHouseholdId();
440	            }
441	        }
442	        return generateHouseholdId(normalizeHouseholdValue(owner.getLastName()),
443	            normalizeHouseholdAddress(owner.getAddress()));
444	    }
445	
446	    /**
447	     * Derives a stable {@code householdId} formatted {@code 'HH-<12 upper-hex>'} from the SHA-256
448	     * digest of the normalized {@code lastName} and {@code address}, so all owners in the same
449	     * household deterministically share the same identifier.
450	     */
451	    private static String generateHouseholdId(String lastName, String address) {
452	        try {
453	            MessageDigest digest = MessageDigest.getInstance("SHA-256");
454	            byte[] hash = digest.digest((lastName + "\u0000" + address).getBytes(StandardCharsets.UTF_8));
455	            StringBuilder sb = new StringBuilder();
456	            for (int i = 0; i < 6; i++) {
457	                sb.append(String.format("%02X", hash[i]));
458	            }
459	            return "HH-" + sb;
460	        } catch (NoSuchAlgorithmException e) {
461	            throw new IllegalStateException("SHA-256 not available", e);
462	        }
463	    }
464	
465	    /**
466	     * Normalizes a household comparison value by trimming, collapsing runs of whitespace into a
467	     * single space and lower-casing, so comparisons ignore case and incidental whitespace.
468	     */
469	    private static String normalizeHouseholdValue(String value) {
470	        if (value == null) {
471	            return "";
472	        }
473	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
474	    }
475	
476	    /**
477	     * Household comparison value for an address: the canonical {@link #normalizeAddress(String)}
478	     * form (never {@code null}), so duplicate detection and the shared household id compare
479	     * addresses using the same normalized representation that is stored and returned.
480	     */
481	    private static String normalizeHouseholdAddress(String address) {
482	        String normalized = normalizeAddress(address);
483	        return normalized == null ? "" : normalized;
484	    }
